/**
 * Liga o <select> de Cultivar ao <select> de BT: escolhendo uma cultivar
 * da lista, o BT e preenchido sozinho. Escolhendo "Outra cultivar", libera
 * um campo de texto para digitar o nome e o BT passa a ser escolhido
 * manualmente pelo usuario.
 *
 * @param {string} idSelectCultivar  id do <select> com a lista de cultivares
 * @param {string} idInputOutra     id do <input type="text"> da cultivar digitada
 * @param {string} idHiddenCultivar id do <input type="hidden" name="cultivar">
 * @param {string} idSelectBt       id do <select name="bt">
 * @param {string} [cultivarAtual]  valor ja salvo (tela de edicao)
 */
function initCultivarBt(idSelectCultivar, idInputOutra, idHiddenCultivar, idSelectBt, cultivarAtual) {
    const selectCultivar = document.getElementById(idSelectCultivar);
    const inputOutra = document.getElementById(idInputOutra);
    const hiddenCultivar = document.getElementById(idHiddenCultivar);
    const selectBt = document.getElementById(idSelectBt);

    if (!selectCultivar || !hiddenCultivar) return;

    // popula as opcoes (uma vez), mantendo "Outra cultivar" (OUTRA) por ultimo
    if (selectCultivar.options.length <= 1) {
        CULTIVARES_ORDEM.forEach(function (nome) {
            const opt = document.createElement("option");
            opt.value = nome;
            opt.textContent = nome;
            selectCultivar.appendChild(opt);
        });
        const optOutra = document.createElement("option");
        optOutra.value = "OUTRA";
        optOutra.textContent = "Outra cultivar";
        selectCultivar.appendChild(optOutra);
    }

    function aplicarSelecao(nome) {
        if (nome === "OUTRA") {
            if (inputOutra) {
                inputOutra.classList.remove("d-none");
            }
            hiddenCultivar.value = (inputOutra ? inputOutra.value : "");
            if (selectBt) {
                selectBt.disabled = false;
            }
        } else {
            if (inputOutra) {
                inputOutra.classList.add("d-none");
                inputOutra.value = "";
            }
            hiddenCultivar.value = nome;
            if (selectBt && nome && CULTIVAR_BT.hasOwnProperty(nome)) {
                selectBt.value = CULTIVAR_BT[nome];
            }
        }
    }

    selectCultivar.addEventListener("change", function () {
        aplicarSelecao(selectCultivar.value);
    });

    if (inputOutra) {
        inputOutra.addEventListener("input", function () {
            hiddenCultivar.value = inputOutra.value;
        });
    }

    // estado inicial (tela de edicao: cultivar ja preenchida)
    if (cultivarAtual) {
        if (CULTIVAR_BT.hasOwnProperty(cultivarAtual)) {
            selectCultivar.value = cultivarAtual;
            aplicarSelecao(cultivarAtual);
        } else {
            selectCultivar.value = "OUTRA";
            if (inputOutra) {
                inputOutra.value = cultivarAtual;
                inputOutra.classList.remove("d-none");
            }
            hiddenCultivar.value = cultivarAtual;
        }
    }
}
